import pytest
from datetime import UTC, datetime

from subject import (
    extract_registry_update,
    _EVENT_TYPE_TO_PHASE,
    _FILE_TOUCH_TOOLS,
    CONSUMER_GROUP,
)
from omnibase_infra.services.session_registry.enum_session_phase import EnumSessionPhase
from omnibase_infra.services.session_registry.enum_session_registry_status import (
    EnumSessionRegistryStatus,
)
from omnibase_infra.services.session_registry.models import ModelSessionRegistryEntry


def test_extract_registry_update_basic_session_started():
    event = {
        "task_id": "task-123",
        "session_id": "session-456",
        "correlation_id": "corr-789",
        "event_type": "session.started",
        "emitted_at": "2025-01-15T10:30:00+00:00",
    }
    result = extract_registry_update(event)
    assert result is not None
    assert isinstance(result, ModelSessionRegistryEntry)
    assert result.task_id == "task-123"
    assert result.status == EnumSessionRegistryStatus.ACTIVE
    assert result.current_phase == EnumSessionPhase.PLANNING
    assert result.session_ids == ["session-456"]
    assert result.correlation_ids == ["corr-789"]
    assert result.last_activity == datetime(2025, 1, 15, 10, 30, tzinfo=UTC)
    assert result.files_touched == []


